# GENERATED by engineering-harness (`harness compose`). Run inside a Maestri terminal:
#   pwsh -File .harness/maestri-roles.ps1 [-Scope current|global]
# Creates or updates one Maestri role per persona (default: scoped to the current workspace).
param([ValidateSet('current', 'global')][string]$Scope = 'current')
$ErrorActionPreference = 'Stop'
$maestri = if (Get-Command maestri -ErrorAction SilentlyContinue) { 'maestri' } else { $env:MAESTRI_CLI }
if (-not $maestri) { throw 'maestri CLI not found: run this inside a Maestri terminal' }
$probe = & $maestri role list 2>&1
if ("$probe" -match 'not the Maestro') { throw 'Run this script in the Maestro terminal (Maestro Mode on): role commands are not available to recruits.' }
$out = & $maestri role write 'Analyst' 'You are the Analyst persona of the engineering harness (PERSONAL profile). Your project is the folder the orchestrator names in your task, by default `EXAMPLES/demo-python-api` under the git repository root (run git rev-parse --show-toplevel); cd there before anything else, because you start inside .maestri/roles and must never commit the .maestri folder. Then read .harness/personas/analyst.md and AGENTS.md in the project and follow them. Run maestri list to see your teammates. Write stage evidence to .harness/runs/<story>/ as the story-delivery workflow requires, keep maestri floor status current, and when a task is done report back with maestri ask to whoever assigned it.' 2>&1
if ($LASTEXITCODE -ne 0 -or "$out" -match 'No role named') {
  & $maestri role create 'Analyst' 'You are the Analyst persona of the engineering harness (PERSONAL profile). Your project is the folder the orchestrator names in your task, by default `EXAMPLES/demo-python-api` under the git repository root (run git rev-parse --show-toplevel); cd there before anything else, because you start inside .maestri/roles and must never commit the .maestri folder. Then read .harness/personas/analyst.md and AGENTS.md in the project and follow them. Run maestri list to see your teammates. Write stage evidence to .harness/runs/<story>/ as the story-delivery workflow requires, keep maestri floor status current, and when a task is done report back with maestri ask to whoever assigned it.' --scope $Scope
  if ($LASTEXITCODE -ne 0) { throw "maestri role create 'Analyst' failed" }
  Write-Output 'created role Analyst'
} else { Write-Output 'updated role Analyst' }
